class Solution {
  public int countWinningSequences(String s) {
    final int MOD = 1_000_000_007;
    int n = s.length(), w = 2 * n + 1;
    long[][] dp = new long[4][w];
    dp[3][n] = 1;
    for (int i = 0; i < n; i++) {
      int a = s.charAt(i) == 'F' ? 0 : s.charAt(i) == 'W' ? 1 : 2;
      long[][] nd = new long[4][w];
      for (int last = 0; last < 4; last++) {
        for (int d = n - i; d <= n + i; d++) {
          long v = dp[last][d];
          if (v == 0) continue;
          for (int b = 0; b < 3; b++) {
            if (b == last) continue;
            int nd2 = d + (b == (a + 1) % 3 ? 1 : a == (b + 1) % 3 ? -1 : 0);
            nd[b][nd2] = (nd[b][nd2] + v) % MOD;
          }
        }
      }
      dp = nd;
    }
    long ans = 0;
    for (int last = 0; last < 3; last++) for (int d = n + 1; d < w; d++) ans += dp[last][d];
    return (int) (ans % MOD);
  }
}
